//! User-mode FlexiKey action dispatcher.
//!
//! A low-level keyboard hook maps CC4.0 scan-code triggers to the same four
//! actions stored in `profile.xml`. Injected events generated by Neo Control
//! carry a private marker and are ignored by the hook, preventing macro loops.

#[derive(Clone, Debug, Default)]
pub struct EngineReport {
    pub keyboard_actions: usize,
    pub mouse_actions: usize,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct CapturedTrigger {
    pub device: u8,
    pub key_code: u16,
    pub name: String,
}

#[derive(Clone, Debug)]
pub struct FlexiKeyEngine {
    #[cfg(windows)]
    available: bool,
    #[cfg(windows)]
    error: Option<String>,
}

#[cfg(any(windows, test))]
pub(crate) fn cc40_key_code_from_parts(virtual_key: u16, scan_code: u16, extended: bool) -> u16 {
    if virtual_key == 0xff || extended {
        if virtual_key != 161 && virtual_key != 144 {
            0xe000 | scan_code
        } else {
            scan_code
        }
    } else if virtual_key != 19 {
        scan_code
    } else {
        57629
    }
}

#[cfg(test)]
mod tests {
    use super::cc40_key_code_from_parts;

    #[test]
    fn cc40_mapping_preserves_ordinary_scan_codes() {
        assert_eq!(cc40_key_code_from_parts(0x87, 0x76, false), 0x76);
    }

    #[test]
    fn cc40_mapping_marks_extended_keys() {
        assert_eq!(cc40_key_code_from_parts(0x2e, 0x53, true), 0xe053);
    }

    #[test]
    fn cc40_mapping_preserves_pause_special_case() {
        assert_eq!(cc40_key_code_from_parts(19, 0x45, false), 57629);
    }

    #[test]
    fn cc40_mouse_mapping_matches_vendor_button_values() {
        assert_eq!(super::cc40_mouse_code(0x0201, 0), Some(1));
        assert_eq!(super::cc40_mouse_code(0x0204, 0), Some(4));
        assert_eq!(super::cc40_mouse_code(0x0207, 0), Some(0x10));
        assert_eq!(super::cc40_mouse_code(0x020b, 1 << 16), Some(0x40));
        assert_eq!(super::cc40_mouse_code(0x020b, 2 << 16), Some(0x100));
    }

    #[cfg(windows)]
    #[test]
    fn hotkey_parser_builds_balanced_chord_sequence() {
        let steps = super::hotkey_steps("Ctrl+Shift+S F24").expect("hotkey parser");
        assert_eq!(steps.len(), 8);
        assert!(
            steps[..3]
                .iter()
                .all(|step| step.kind == neo_control_protocol::MacroStepKind::Make)
        );
        assert!(
            steps[3..6]
                .iter()
                .all(|step| step.kind == neo_control_protocol::MacroStepKind::Break)
        );
        assert_eq!(steps[6].kind, neo_control_protocol::MacroStepKind::Make);
        assert_eq!(steps[7].kind, neo_control_protocol::MacroStepKind::Break);
    }

    #[cfg(windows)]
    #[test]
    fn hotkey_parser_rejects_unknown_names() {
        assert!(super::hotkey_steps("Ctrl+NotAKey").is_err());
    }
}

#[cfg(any(windows, test))]
pub(crate) fn cc40_mouse_code(message: u32, mouse_data: u32) -> Option<u16> {
    match message {
        0x0201 | 0x0202 => Some(1),
        0x0204 | 0x0205 => Some(4),
        0x0207 | 0x0208 => Some(0x10),
        0x020b | 0x020c => match mouse_data >> 16 {
            1 => Some(0x40),
            2 => Some(0x100),
            _ => None,
        },
        _ => None,
    }
}

#[cfg(windows)]
pub(crate) fn hotkey_steps(text: &str) -> Result<Vec<neo_control_protocol::MacroStep>, String> {
    platform::hotkey_steps(text)
}

#[cfg(not(windows))]
pub(crate) fn hotkey_steps(_text: &str) -> Result<Vec<neo_control_protocol::MacroStep>, String> {
    Err("hotkey recording is only available on Windows".to_owned())
}

#[cfg(windows)]
mod platform {
    use std::collections::{HashMap, HashSet};
    use std::ffi::OsStr;
    use std::os::windows::ffi::OsStrExt;
    use std::ptr;
    use std::sync::mpsc::{self, Sender};
    use std::sync::{Mutex, OnceLock};
    use std::thread;
    use std::time::Duration;

    use neo_control_protocol::{
        FlexiKeyAction, FlexiKeyDevice, FlexiKeyProfile, MacroStep, MacroStepKind,
    };
    use windows_sys::Win32::Foundation::{LPARAM, LRESULT, WPARAM};
    use windows_sys::Win32::System::LibraryLoader::GetModuleHandleW;
    use windows_sys::Win32::UI::Input::KeyboardAndMouse::{
        GetKeyNameTextW, INPUT, INPUT_0, INPUT_KEYBOARD, KEYBDINPUT, KEYEVENTF_EXTENDEDKEY,
        KEYEVENTF_KEYUP, KEYEVENTF_SCANCODE, KEYEVENTF_UNICODE, MAPVK_VK_TO_VSC,
        MAPVK_VK_TO_VSC_EX, MAPVK_VSC_TO_VK_EX, MapVirtualKeyW, SendInput,
    };
    use windows_sys::Win32::UI::Shell::ShellExecuteW;
    use windows_sys::Win32::UI::WindowsAndMessaging::{
        CallNextHookEx, DispatchMessageW, GetMessageW, KBDLLHOOKSTRUCT, LLKHF_EXTENDED,
        LLKHF_INJECTED, MSG, MSLLHOOKSTRUCT, SetWindowsHookExW, TranslateMessage,
        UnhookWindowsHookEx, WH_KEYBOARD_LL, WH_MOUSE_LL, WM_KEYDOWN, WM_KEYUP, WM_LBUTTONDOWN,
        WM_LBUTTONUP, WM_MBUTTONDOWN, WM_MBUTTONUP, WM_RBUTTONDOWN, WM_RBUTTONUP, WM_SYSKEYDOWN,
        WM_SYSKEYUP, WM_XBUTTONDOWN, WM_XBUTTONUP,
    };

    use super::{CapturedTrigger, EngineReport, FlexiKeyEngine};

    const INJECTION_MAGIC: usize = 0x4e45_4f46; // "NEOF"
    const HOOK_START_TIMEOUT: Duration = Duration::from_secs(3);

    struct EngineState {
        keyboard_actions: HashMap<u16, FlexiKeyAction>,
        mouse_actions: HashMap<u16, FlexiKeyAction>,
        keyboard_down: HashSet<u16>,
        mouse_down: HashSet<u16>,
        sender: Sender<FlexiKeyAction>,
    }

    enum CaptureState {
        Idle,
        Armed,
        Down { trigger: CapturedTrigger },
        Ready(CapturedTrigger),
    }

    static ENGINE: OnceLock<Mutex<EngineState>> = OnceLock::new();
    static CAPTURE: OnceLock<Mutex<CaptureState>> = OnceLock::new();

    impl FlexiKeyEngine {
        pub fn start() -> Self {
            if ENGINE.get().is_none() {
                let (sender, receiver) = mpsc::channel();
                thread::spawn(move || action_worker(receiver));
                let _ = ENGINE.set(Mutex::new(EngineState {
                    keyboard_actions: HashMap::new(),
                    mouse_actions: HashMap::new(),
                    keyboard_down: HashSet::new(),
                    mouse_down: HashSet::new(),
                    sender,
                }));
            }

            let (hook_tx, hook_rx) = mpsc::channel();
            thread::spawn(move || unsafe {
                let module = GetModuleHandleW(ptr::null());
                let keyboard = SetWindowsHookExW(WH_KEYBOARD_LL, Some(keyboard_hook), module, 0);
                let mouse = SetWindowsHookExW(WH_MOUSE_LL, Some(mouse_hook), module, 0);
                if keyboard.is_null() || mouse.is_null() {
                    if !keyboard.is_null() {
                        UnhookWindowsHookEx(keyboard);
                    }
                    if !mouse.is_null() {
                        UnhookWindowsHookEx(mouse);
                    }
                    let _ = hook_tx.send(Err(std::io::Error::last_os_error().to_string()));
                    return;
                }
                let _ = hook_tx.send(Ok(()));
                let mut message = MSG::default();
                while GetMessageW(&mut message, ptr::null_mut(), 0, 0) > 0 {
                    TranslateMessage(&message);
                    DispatchMessageW(&message);
                }
                UnhookWindowsHookEx(keyboard);
                UnhookWindowsHookEx(mouse);
            });

            let (available, error) = match hook_rx.recv_timeout(HOOK_START_TIMEOUT) {
                Ok(Ok(())) => (true, None),
                Ok(Err(error)) => (false, Some(format!("keyboard hook failed: {error}"))),
                Err(error) => (
                    false,
                    Some(format!("keyboard hook start timed out: {error}")),
                ),
            };
            if available {
                log_line("keyboard hook active");
            } else if let Some(error) = &error {
                log_line(error);
            }
            Self { available, error }
        }

        pub fn update_profile(
            &self,
            profile: Option<&FlexiKeyProfile>,
        ) -> Result<EngineReport, String> {
            if !self.available {
                return Err(self
                    .error
                    .clone()
                    .unwrap_or_else(|| "keyboard hook unavailable".to_owned()));
            }
            let mut report = EngineReport::default();
            let mut keyboard_actions = HashMap::new();
            let mut mouse_actions = HashMap::new();
            if let Some(profile) = profile {
                for binding in &profile.bindings {
                    let trigger = u16::try_from(binding.key_code).map_err(|_| {
                        format!(
                            "trigger {} in profile {} does not fit 16 bits",
                            binding.key_code, profile.name
                        )
                    })?;
                    match binding.device {
                        FlexiKeyDevice::Keyboard if profile.keyboard_enabled => {
                            if keyboard_actions
                                .insert(trigger, binding.action.clone())
                                .is_some()
                            {
                                return Err(format!(
                                    "profile {} contains duplicate keyboard trigger {:#06x}",
                                    profile.name, trigger
                                ));
                            }
                            report.keyboard_actions += 1;
                        }
                        FlexiKeyDevice::Mouse if profile.mouse_enabled => {
                            if mouse_actions
                                .insert(trigger, binding.action.clone())
                                .is_some()
                            {
                                return Err(format!(
                                    "profile {} contains duplicate mouse trigger {:#06x}",
                                    profile.name, trigger
                                ));
                            }
                            report.mouse_actions += 1;
                        }
                        _ => {}
                    }
                }
            }
            let Some(engine) = ENGINE.get() else {
                return Err("FlexiKey engine was not initialized".to_owned());
            };
            let mut engine = engine
                .lock()
                .map_err(|_| "FlexiKey engine lock was poisoned".to_owned())?;
            engine.keyboard_actions = keyboard_actions;
            engine.mouse_actions = mouse_actions;
            engine.keyboard_down.clear();
            engine.mouse_down.clear();
            log_line(&format!(
                "profile loaded: {} keyboard action(s), {} mouse action(s)",
                report.keyboard_actions, report.mouse_actions
            ));
            Ok(report)
        }

        pub fn arm_capture(&self) -> Result<(), String> {
            if !self.available {
                return Err(self
                    .error
                    .clone()
                    .unwrap_or_else(|| "input hook unavailable".to_owned()));
            }
            let capture = CAPTURE.get_or_init(|| Mutex::new(CaptureState::Idle));
            let mut capture = capture
                .lock()
                .map_err(|_| "trigger capture lock was poisoned".to_owned())?;
            *capture = CaptureState::Armed;
            log_line("trigger capture armed");
            Ok(())
        }

        pub fn cancel_capture(&self) {
            if let Some(capture) = CAPTURE.get()
                && let Ok(mut capture) = capture.lock()
            {
                *capture = CaptureState::Idle;
            }
        }

        pub fn take_captured_trigger(&self) -> Option<CapturedTrigger> {
            let capture = CAPTURE.get()?;
            let mut capture = capture.lock().ok()?;
            let CaptureState::Ready(trigger) = &*capture else {
                return None;
            };
            let trigger = trigger.clone();
            *capture = CaptureState::Idle;
            log_line(&format!(
                "trigger captured: device={} code={:#06x} name={}",
                trigger.device, trigger.key_code, trigger.name
            ));
            Some(trigger)
        }
    }

    fn call_next_hook(code: i32, wparam: WPARAM, lparam: LPARAM) -> LRESULT {
        unsafe { CallNextHookEx(ptr::null_mut(), code, wparam, lparam) }
    }

    fn map_virtual_key(code: u32, mode: u32) -> u32 {
        unsafe { MapVirtualKeyW(code, mode) }
    }

    unsafe extern "system" fn keyboard_hook(code: i32, wparam: WPARAM, lparam: LPARAM) -> LRESULT {
        if code < 0 {
            return call_next_hook(code, wparam, lparam);
        }
        let message = wparam as u32;
        let down = message == WM_KEYDOWN || message == WM_SYSKEYDOWN;
        let up = message == WM_KEYUP || message == WM_SYSKEYUP;
        if !down && !up {
            return call_next_hook(code, wparam, lparam);
        }

        let keyboard = unsafe { &*(lparam as *const KBDLLHOOKSTRUCT) };
        if keyboard.flags & LLKHF_INJECTED != 0 && keyboard.dwExtraInfo == INJECTION_MAGIC {
            return call_next_hook(code, wparam, lparam);
        }
        let key = cc40_key_code(keyboard);
        if down
            && capture_down(CapturedTrigger {
                device: FlexiKeyDevice::Keyboard.as_u8(),
                key_code: key,
                name: keyboard_name(keyboard),
            })
        {
            return 1;
        }
        if up && capture_up(FlexiKeyDevice::Keyboard.as_u8(), key) {
            return 1;
        }
        let Some(engine) = ENGINE.get() else {
            return call_next_hook(code, wparam, lparam);
        };
        let Ok(mut engine) = engine.lock() else {
            return call_next_hook(code, wparam, lparam);
        };
        let Some(action) = engine.keyboard_actions.get(&key).cloned() else {
            drop(engine);
            return call_next_hook(code, wparam, lparam);
        };
        if down {
            if engine.keyboard_down.insert(key) {
                let _ = engine.sender.send(action);
            }
        } else {
            engine.keyboard_down.remove(&key);
        }
        drop(engine);
        1
    }

    fn cc40_key_code(keyboard: &KBDLLHOOKSTRUCT) -> u16 {
        super::cc40_key_code_from_parts(
            keyboard.vkCode as u16,
            keyboard.scanCode as u16,
            keyboard.flags & LLKHF_EXTENDED != 0,
        )
    }

    unsafe extern "system" fn mouse_hook(code: i32, wparam: WPARAM, lparam: LPARAM) -> LRESULT {
        if code < 0 {
            return call_next_hook(code, wparam, lparam);
        }
        let message = wparam as u32;
        let down = matches!(
            message,
            WM_LBUTTONDOWN | WM_RBUTTONDOWN | WM_MBUTTONDOWN | WM_XBUTTONDOWN
        );
        let up = matches!(
            message,
            WM_LBUTTONUP | WM_RBUTTONUP | WM_MBUTTONUP | WM_XBUTTONUP
        );
        if !down && !up {
            return call_next_hook(code, wparam, lparam);
        }
        let mouse = unsafe { &*(lparam as *const MSLLHOOKSTRUCT) };
        if matches!(message, WM_XBUTTONDOWN | WM_XBUTTONUP) {
            log_line(&format!(
                "mouse xbutton event: message={message:#06x} data={:#010x}",
                mouse.mouseData
            ));
        }
        let Some(button) = super::cc40_mouse_code(message, mouse.mouseData) else {
            return call_next_hook(code, wparam, lparam);
        };
        if down
            && capture_down(CapturedTrigger {
                device: FlexiKeyDevice::Mouse.as_u8(),
                key_code: button,
                name: mouse_button_name(button).to_owned(),
            })
        {
            return 1;
        }
        if up && capture_up(FlexiKeyDevice::Mouse.as_u8(), button) {
            return 1;
        }
        let Some(engine) = ENGINE.get() else {
            return call_next_hook(code, wparam, lparam);
        };
        let Ok(mut engine) = engine.lock() else {
            return call_next_hook(code, wparam, lparam);
        };
        let Some(action) = engine.mouse_actions.get(&button).cloned() else {
            drop(engine);
            return call_next_hook(code, wparam, lparam);
        };
        if down {
            if engine.mouse_down.insert(button) {
                let _ = engine.sender.send(action);
            }
        } else {
            engine.mouse_down.remove(&button);
        }
        drop(engine);
        1
    }

    fn capture_down(trigger: CapturedTrigger) -> bool {
        let capture = CAPTURE.get_or_init(|| Mutex::new(CaptureState::Idle));
        let Ok(mut capture) = capture.lock() else {
            return false;
        };
        if matches!(*capture, CaptureState::Armed) {
            *capture = CaptureState::Down { trigger };
            true
        } else {
            false
        }
    }

    fn capture_up(device: u8, key_code: u16) -> bool {
        let Some(capture) = CAPTURE.get() else {
            return false;
        };
        let Ok(mut capture) = capture.lock() else {
            return false;
        };
        let ready = match &*capture {
            CaptureState::Down { trigger }
                if trigger.device == device && trigger.key_code == key_code =>
            {
                Some(trigger.clone())
            }
            _ => None,
        };
        if let Some(trigger) = ready {
            *capture = CaptureState::Ready(trigger);
            true
        } else {
            false
        }
    }

    fn keyboard_name(keyboard: &KBDLLHOOKSTRUCT) -> String {
        let extended = if keyboard.flags & LLKHF_EXTENDED != 0 {
            1_i32 << 24
        } else {
            0
        };
        let lparam = ((keyboard.scanCode as i32) << 16) | extended;
        let mut buffer = [0_u16; 64];
        let length = unsafe { GetKeyNameTextW(lparam, buffer.as_mut_ptr(), buffer.len() as i32) };
        if length > 0 {
            String::from_utf16_lossy(&buffer[..length as usize])
        } else {
            format!("Key {:#06x}", cc40_key_code(keyboard))
        }
    }

    fn mouse_button_name(code: u16) -> &'static str {
        match code {
            1 => "Mouse Left",
            4 => "Mouse Right",
            0x10 => "Mouse Middle",
            0x40 => "Mouse Back",
            0x100 => "Mouse Forward",
            _ => "Mouse Button",
        }
    }

    pub(super) fn hotkey_steps(text: &str) -> Result<Vec<MacroStep>, String> {
        if text.len() > 512 {
            return Err("快捷键文本过长".to_owned());
        }
        let chords = text.split_whitespace().collect::<Vec<_>>();
        if chords.is_empty() {
            return Err("请输入快捷键，例如 Ctrl+Shift+S".to_owned());
        }
        let mut steps = Vec::new();
        for chord in chords {
            let mut keys = Vec::new();
            for token in chord.split('+').filter(|token| !token.trim().is_empty()) {
                keys.push(resolve_macro_key(token.trim())?);
            }
            if keys.is_empty() {
                return Err(format!("快捷键组合 {chord:?} 没有有效按键"));
            }
            for (key_code, display) in &keys {
                steps.push(MacroStep {
                    key_code: i64::from(*key_code),
                    kind: MacroStepKind::Make,
                    delay_ms: 10,
                    group: 0,
                    display: display.clone(),
                });
            }
            for (key_code, display) in keys.iter().rev() {
                steps.push(MacroStep {
                    key_code: i64::from(*key_code),
                    kind: MacroStepKind::Break,
                    delay_ms: 10,
                    group: 0,
                    display: display.clone(),
                });
            }
            if steps.len() > 64 {
                return Err("快捷键动作过多，请拆分成更短的组合".to_owned());
            }
        }
        Ok(steps)
    }

    fn resolve_macro_key(token: &str) -> Result<(u16, String), String> {
        if let Some(raw) = token
            .strip_prefix("0x")
            .or_else(|| token.strip_prefix("0X"))
        {
            let key_code =
                u16::from_str_radix(raw, 16).map_err(|_| format!("无法识别按键代码 {token:?}"))?;
            if key_code == 0 {
                return Err("按键代码不能为 0".to_owned());
            }
            return Ok((key_code, token.to_ascii_uppercase()));
        }

        let lower = token.to_ascii_lowercase();
        let virtual_key: u16 = match lower.as_str() {
            "ctrl" | "control" => 0x11,
            "shift" => 0x10,
            "alt" => 0x12,
            "win" | "windows" | "meta" => 0x5b,
            "tab" => 0x09,
            "enter" | "return" => 0x0d,
            "esc" | "escape" => 0x1b,
            "space" => 0x20,
            "backspace" | "back" => 0x08,
            "delete" | "del" => 0x2e,
            "insert" | "ins" => 0x2d,
            "home" => 0x24,
            "end" => 0x23,
            "pageup" | "pgup" => 0x21,
            "pagedown" | "pgdn" => 0x22,
            "up" => 0x26,
            "down" => 0x28,
            "left" => 0x25,
            "right" => 0x27,
            "printscreen" | "prtsc" => 0x2c,
            "pause" => 0x13,
            "capslock" => 0x14,
            "numlock" => 0x90,
            "scrolllock" => 0x91,
            _ => {
                if let Some(number) = lower
                    .strip_prefix('f')
                    .and_then(|value| value.parse::<u8>().ok())
                {
                    if (1..=24).contains(&number) {
                        0x6f + u16::from(number)
                    } else {
                        return Err(format!("不支持功能键 {token:?}"));
                    }
                } else if token.len() == 1 {
                    let character = token.chars().next().unwrap_or_default();
                    if character.is_ascii_alphanumeric() {
                        character.to_ascii_uppercase() as u16
                    } else {
                        return Err(format!("暂不支持字符键 {token:?}，请使用 0xNN 扫描码"));
                    }
                } else {
                    return Err(format!("无法识别按键 {token:?}"));
                }
            }
        };

        let mapped = map_virtual_key(u32::from(virtual_key), MAPVK_VK_TO_VSC_EX);
        let (scan_code, extended) = if mapped & 0xff00 == 0xe000 {
            ((mapped & 0xff) as u16, true)
        } else {
            let scan_code = (mapped & 0xff) as u16;
            let fallback = map_virtual_key(u32::from(virtual_key), MAPVK_VK_TO_VSC);
            let scan_code = if scan_code == 0 {
                (fallback & 0xff) as u16
            } else {
                scan_code
            };
            (scan_code, is_extended_key(virtual_key))
        };
        if scan_code == 0 {
            return Err(format!("系统没有为按键 {token:?} 提供扫描码"));
        }
        Ok((
            super::cc40_key_code_from_parts(virtual_key, scan_code, extended),
            token.to_owned(),
        ))
    }

    fn is_extended_key(virtual_key: u16) -> bool {
        matches!(
            virtual_key,
            0x21..=0x2e | 0x5b | 0x5c | 0x6f | 0x90 | 0xa3 | 0xa5
        )
    }

    fn action_worker(receiver: mpsc::Receiver<FlexiKeyAction>) {
        while let Ok(action) = receiver.recv() {
            if let Err(error) = execute_action(&action) {
                log_line(&format!("action failed: {error}"));
            }
        }
    }

    fn execute_action(action: &FlexiKeyAction) -> Result<(), String> {
        match action {
            FlexiKeyAction::Keypress { steps } => {
                send_steps(steps)?;
                log_line("keypress action dispatched");
            }
            FlexiKeyAction::Launch { app_path, .. } => {
                launch(app_path)?;
                log_line(&format!("launch action dispatched: {app_path}"));
            }
            FlexiKeyAction::Text {
                start_keys,
                text,
                send_keys,
            } => {
                send_steps(start_keys)?;
                send_unicode(text)?;
                send_steps(send_keys)?;
                log_line("text action dispatched");
            }
            FlexiKeyAction::Disable => {
                log_line("trigger disabled");
            }
        }
        Ok(())
    }

    fn send_steps(steps: &[MacroStep]) -> Result<(), String> {
        for step in steps {
            if step.delay_ms > 0 {
                thread::sleep(Duration::from_millis(
                    u64::try_from(step.delay_ms.min(5000)).unwrap_or(0),
                ));
            }
            let key = u16::try_from(step.key_code)
                .map_err(|_| format!("macro key {} does not fit 16 bits", step.key_code))?;
            let up = step.kind == MacroStepKind::Break;
            send_scan_key(key, up)?;
        }
        Ok(())
    }

    fn send_scan_key(key: u16, up: bool) -> Result<(), String> {
        let extended = key >= 0xe000;
        let scan = if extended { key & 0xff } else { key };
        let virtual_key = map_virtual_key(u32::from(scan), MAPVK_VSC_TO_VK_EX) as u16;
        let mut flags = 0;
        if extended {
            flags |= KEYEVENTF_EXTENDEDKEY;
        }
        if up {
            flags |= KEYEVENTF_KEYUP;
        }
        let flags = if virtual_key == 0 {
            flags | KEYEVENTF_SCANCODE
        } else {
            flags
        };
        send_input(&[keyboard_input(scan, virtual_key, flags)?])
    }

    fn send_unicode(text: &str) -> Result<(), String> {
        for unit in text.encode_utf16() {
            send_input(&[
                keyboard_input(unit, 0, KEYEVENTF_UNICODE)?,
                keyboard_input(unit, 0, KEYEVENTF_UNICODE | KEYEVENTF_KEYUP)?,
            ])?;
            thread::sleep(Duration::from_millis(2));
        }
        Ok(())
    }

    fn keyboard_input(scan: u16, virtual_key: u16, flags: u32) -> Result<INPUT, String> {
        if scan == 0 && virtual_key == 0 {
            return Err("keyboard input has neither scan nor virtual key".to_owned());
        }
        Ok(INPUT {
            r#type: INPUT_KEYBOARD,
            Anonymous: INPUT_0 {
                ki: KEYBDINPUT {
                    wVk: virtual_key,
                    wScan: scan,
                    dwFlags: flags,
                    time: 0,
                    dwExtraInfo: INJECTION_MAGIC,
                },
            },
        })
    }

    fn send_input(inputs: &[INPUT]) -> Result<(), String> {
        let sent = unsafe {
            SendInput(
                inputs.len() as u32,
                inputs.as_ptr(),
                std::mem::size_of::<INPUT>() as i32,
            )
        };
        if sent != inputs.len() as u32 {
            return Err(std::io::Error::last_os_error().to_string());
        }
        Ok(())
    }

    fn launch(path: &str) -> Result<(), String> {
        let operation = wide("open");
        let path = wide(path);
        let result = unsafe {
            ShellExecuteW(
                ptr::null_mut(),
                operation.as_ptr(),
                path.as_ptr(),
                ptr::null(),
                ptr::null(),
                1,
            )
        } as isize;
        if result <= 32 {
            return Err(format!("ShellExecuteW returned {result}"));
        }
        Ok(())
    }

    fn wide(value: &str) -> Vec<u16> {
        OsStr::new(value)
            .encode_wide()
            .chain(std::iter::once(0))
            .collect()
    }

    fn log_line(message: &str) {
        use std::io::Write as _;
        let Some(path) = std::env::var_os("NEO_CONTROL_FLEXIKEY_LOG").map(std::path::PathBuf::from)
        else {
            return;
        };
        let Some(parent) = path.parent() else {
            return;
        };
        if std::fs::create_dir_all(parent).is_err() {
            return;
        }
        if let Ok(mut file) = std::fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(path)
        {
            let _ = writeln!(file, "{message}");
        }
    }
}

